def compute_cumulative_sum_for_second(n, m):
    k = n - n * comb(n - 1, n - 2) - compt(n - 2)
    return k, n * comb(n - 1, k)


def map_mod(c_k, l_factor, r_factor, s, r, k, mod):
    res = []
    for x in range(r + 1):
        r_l = l_factor; m_k, m_r = compute_multilog(s, k/r_factor)
        for i in range(m_k[0]):
            res.append(x)
        for i in range(m_r[0] - m_r[1]):
