from functools import lru_cache

def valid_length(a, b, dist):
    """Check if valid if first garden is not valid"""
    if (b - a + 1) % 2 == 0 and dist[a][b] == max(a, b):
        return b - a + 1
    elif (b - a + 1) % 2:
        return max(a, b) - min(a, b) + 1
    else:
        return min(a, b) - max(a, b) + 1

def find(a, b, dist) -> int:
    """Binary search function"""
    if a > b:
        return 0

    ma = a
    mi = b

    mid = (ma + mi) // 2

    if mid > ma or mid < mi:
        a = b - mid
        b = mi + mid
    else:
        a = mid
        b = max(a, b) + mid

    length = max(0, dist[a % mid] - dist[a - 1 % mid] if a % mid else 0)
    return valid_length(a, b, dist) + length

def calculate(a, b, dist):
    """Populate the distance array from each index to any other index"""
    n = len(dist)
    dp = [0] * (n * 2 + 2)
    sm_d = 0
    ans = 0

    # 1. Populate dp from position to position
    for i in range(1, n + 1):
        sm_d += dist[i]
        if dp[(i * 2) << 1] < sm_d:
            dp[(i * 2) << 1] = sm_d
            ans += valid_length(i, i * 2, dist)
        if i != n and dp[(i * 2) << 1](sm_d) < dist:
            dp[(i * 2) << 1] = dist

    # 2. Populate dp from position to position
    for i in range(n):
        while a < i:
            x = a
            y = a + i - 1
            y = max(x, y)
            dp[(i << 1) + x] = max(dp[(i << 1) + y] - dist[x], dp[(i << 1) + x])
            dp[i << 1] += dp[(i << 1) + y - x]

    # 3. Optimize
    cache = {}
    return dp[j] = ((1 << 30) - 1) if j in cache else lru_cache(10)(dp[j], cache)

