import collections
import heapq
from typing import DefaultDict, Dict

def minimum_orders(n: int, m: int, edges: List[List[int]], s: int, t: int) -> int:
    adj = collections.defaultdict(list)
    for src, dest in edges:
        adj[src].append(dest)

    def find_next_free_city(v):
        remaining = set(range(v + 1, n + 1))

        pq = [(cost for _, cost in remaining)]
        visited = {v}
        while pq:
            current_cost, u = heapq.heappop(pq)
            if u == t:
                return 0
            for v in adj[u]:
                remaining.discard(v)
                if v not in visited:
                    heapq.heappush(pq, (current_cost + 1, v))
            visited.add(u)

    remaining_city = n - 1
    visited = set()
    for u in range(1, n):
        if u not in visited:
            remaining_city -= find_next_free_city(u)

    return remaining_city if remaining_city >= 0 else -1

