from collections import Counter
from math import gcd
from functools import reduce

def find_answer(numbers, target):
    count = Counter(numbers)
    pairs = 0
    for number, frequency in count.items():
        if number == target:
            pairs += 1
        else:
            for divisor in range(1, gcd(number, target) + 1):
                if number % divisor == 0 and target % divisor:
                    pairs += count[number // divisor] * count[target // divisor]
    return pairs

