            elif low <= middle:
                hightree = hi
                return half_sum(hi, res, low + 1, side = left)

class NumstMN(Numst):
    def __init__(self, add_edge):
        self.add_edge = add_edge
    def make_numsttree(self):
        self.nodes_ = ListOfSumNMult(self.add_edge)

