from collections import deque

def find_cyclic_list(s):
    n = len(s)
    indices = [-1] * 26
    num_occurrences = [0] * 26

    for i, ch in enumerate(s):
        num_occurrences[ord(ch) - ord('a')] += 1
        indices[ord(ch) - ord('a')] = i

    cyclic_lists = []
    current = deque()
    for i, ch in enumerate(s):
        if indices[ord(ch) - ord('a')] < 0:
            continue
        if num_occurrences[ord(ch) - ord('a')] == 0:
            current.append((ch, i))
            indices[ord(ch) - ord('a')] = n
        for _ in range(num_occurrences[ord(ch) - ord('a')]):
            first_char, last_char = current.popleft()
            if indices[first_char - ord('a')] >= 0 and indices[first_char - ord('a')] <= last_char:
                to_reverse = s[first_char:last_char + 1]
                num_occurrences[ord(first_char) - ord('a')] = 0
                cyclic_lists.append(to_reverse[::-1])
                current.append((first_char, indices[first_char - ord('a')]))
                for _ in range(indices[first_char - ord('a')] - len(to_reverse)):
                    current.appendleft('a')
                for _ in range(n - indices[first_char]):
                    current.append('a')
                indices[ord(first_char) - ord('a')] = len(to_reverse) - 1
                current.append((first_char, len(to_reverse) - 1))
                current.append((last_char % len(to_reverse), len(to_reverse) - 1))

    return cyclic_lists

def obtainable_job_categories(s):
    cyclic_lists = find_cyclic_list(s)
    obtainable = set()
    for i, j in cyclic_lists:
        if s[i:j+1] not in obtainable:
            obtainable.add(s[i:j+1])
        for k in range(i, j+1):
            obtainable.add(s[:k] + 'c' + s[k+1:])
    return list(sorted(obtainable))

n, a, b = map(int, input().split())
s = input()
ans = obtainable_job_categories(s)
print(len(ans))
for item in ans:
    print(item)
