import sys
from math import sqrt

def min_tree_length(coords):
    n = len(coords)
    if n % 2:
        return -1  # Odd number of nodes, cannot form a binary tree

    distances = sorted([sqrt(x**2 + y**2) for x, y in coords])

    def binary_tree_length(arr, i):
        if n - i <= i:
            return 0
        total = 0
        for j, d in enumerate(arr[i:]):
            total += d
            if arr[j] * 2 + j > i + n:
                break
        if j + 2 * i < len(arr) // 2:
            total += binary_tree_length(arr, n - i // 2)
        return total

    return binary_tree_length(distances, n // 2)

n = int(input().strip())
coords = [None] * n

for i in range(n):
    x, y = map(int, input().strip().split())
    coords[i] = (x, y)

print(min_tree_length(coords))
